# -*- coding: utf-8 -*-
import os, glob

ROOT = r'D:/repository'
EXCLUDE = ('node_modules','dist','.git','logs','LOG_PATH_IS_UNDEFINED','test-results',
           'memory-migration-archive','openviking-data','.dsh')
def allfiles():
    out=[]
    for dp,dns,fns in os.walk(ROOT):
        dns[:] = [d for d in dns if d not in EXCLUDE]
        for f in fns:
            if f.endswith(('.vue','.js','.ts','.json','.scss','.css','.md','.yaml','.yml','.cjs')):
                out.append(os.path.join(dp,f))
    return out
ALL=allfiles()
def find(rel):
    return glob.glob(os.path.join(ROOT,'**',rel),recursive=True)
def grep(token,limit=8):
    res=[]
    for fp in ALL:
        try:t=open(fp,encoding='utf-8',errors='ignore').read()
        except:continue
        if token in t:
            ls=[l.strip() for l in t.splitlines() if token in l][:2]
            res.append(os.path.relpath(fp,ROOT).replace('\\','/')+' :: '+' | '.join(ls)[:200])
            if len(res)>=limit:break
    return res
out=[]
def sec(t,ls): out.append('### '+t); out.extend(ls or ['(none)']); out.append('')

# IDX3 dsh-token-guard source in ~/.dsh and skills/dsh
for base in [r'C:/Users/Administrator/.dsh', r'D:/repository/skills/dsh']:
    hits=[]
    for dp,dns,fns in os.walk(base):
        dns[:]=[d for d in dns if d not in ('node_modules','.git')]
        for f in fns:
            if f.endswith(('.js','.mjs','.cjs','.ts','.json','.md','.yaml')):
                try:t=open(os.path.join(dp,f),encoding='utf-8',errors='ignore').read()
                except:continue
                if 'readBudgetTokens' in t or 'token-guard' in t.lower():
                    hits.append(os.path.relpath(os.path.join(dp,f),base)[:120])
    sec('IDX3 token-guard source @ '+base, hits[:10])

# IDX4 plan file
pf=[]
for base in [r'D:/plan', r'D:/repository/skills']:
    pf += glob.glob(os.path.join(base,'**','openviking-optimization-20261113*'),recursive=True)
sec('IDX4 plan file', pf[:10])

# IDX6 ov.conf hy3 vlm
ovp=r'C:/Users/Administrator/.openviking/ov.conf'
if os.path.exists(ovp):
    t=open(ovp,encoding='utf-8',errors='ignore').read()
    sec('IDX6 ov.conf hy3 lines',[l.strip() for l in t.splitlines() if 'hy3' in l.lower() or 'vlm' in l.lower()][:10])
else:
    sec('IDX6 ov.conf','(ov.conf not found at '+ovp+')')

# IDX9 园区公共收益 operlog values
for p in find('system/operlog/index.vue'):
    if '园区公共收益' in p and 'node_modules' not in p:
        t=open(p,encoding='utf-8',errors='ignore').read()
        sec('IDX9 operlog values',[l.strip() for l in t.splitlines() if 'moduleName' in l or 'businessName' in l][:6])

# IDX13 graph.py source definitions
for p in find('graph.py'):
    if 'langgraph-orchestrator' in p:
        t=open(p,encoding='utf-8',errors='ignore').read()
        sec('IDX13 '+os.path.relpath(p,ROOT),[l.strip() for l in t.splitlines() if 'def _readonly_read_ok' in l or 'def node_security_guard' in l or 'fail' in l.lower() and 'deny' in l.lower()][:8])

# IDX15 contract/index.vue s16-main__title in real source
for p in find('contract/index.vue'):
    if 'node_modules' not in p:
        t=open(p,encoding='utf-8',errors='ignore').read()
        if 's16-main__title' in t or 's16-side' in t:
            sec('IDX15 '+os.path.relpath(p,ROOT),[l.strip() for l in t.splitlines() if 's16-main__title' in l or 's16-side' in l][:6])

# IDX18 complexChange queryParams.bizState default in 苏住房G
for p in find('complexChange/index.vue'):
    if '苏住房G' in p and 'node_modules' not in p:
        t=open(p,encoding='utf-8',errors='ignore').read()
        sec('IDX18 '+os.path.relpath(p,ROOT),[l.strip() for l in t.splitlines() if 'bizState' in l][:10])

# IDX22 onButtonClick in real source 园区公共收益 zs-operate-column.vue
for p in find('zs-operate-column.vue'):
    if '园区公共收益' in p and 'node_modules' not in p:
        t=open(p,encoding='utf-8',errors='ignore').read()
        sec('IDX22 '+os.path.relpath(p,ROOT),[l.strip() for l in t.splitlines() if 'onButtonClick' in l or 'isButtonDisabled' in l][:8])

# IDX24 AccountListTable :form
for p in find('AccountListTable.vue'):
    if '园区公共收益' in p and 'node_modules' not in p:
        t=open(p,encoding='utf-8',errors='ignore').read()
        sec('IDX24 '+os.path.relpath(p,ROOT),[l.strip() for l in t.splitlines() if ':form' in l or '$attrs' in l][:8])

# IDX25 coerceIdFieldValue real source
sec('IDX25 coerceIdFieldValue (real source)', grep('coerceIdFieldValue'))

# IDX29 MarketHeader.vue real source (non-skills)
mh=[p for p in find('MarketHeader.vue') if 'node_modules' not in p]
sec('IDX29 MarketHeader.vue', [os.path.relpath(p,ROOT) for p in mh][:10])
sec('IDX29 market-monitor route (real source)', grep("path: '/market-monitor'"))

# IDX31 mp-weixin-system-info.js real source anywhere
sec('IDX31 polyfill file (real)', [os.path.relpath(p,ROOT) for p in find('mp-weixin-system-info.js') if 'node_modules' not in p])

# IDX34 getStatIconUrl real source
sec('IDX34 getStatIconUrl (real)', grep('getStatIconUrl'))

# IDX35 投资推送 dir
sec('IDX35 投资推送', [d for d in os.listdir(ROOT) if '投资' in d or '推送' in d])

open(r'C:/Users/Administrator/.dsh/cache/memory-audit/verify3_out.txt','w',encoding='utf-8').write('\n'.join(out))
print('ok',len(out))

